INSERT OR IGNORE INTO settings (id, data) VALUES (1, '{"name": "Rayane", "role": "Architecte", "heroKicker": "Architecture\nDesign\nProjets", "tagline": "Des espaces durables pour demain", "heroImage": "/examples/hero.jpg", "aboutImage": "/examples/about.jpg", "aboutText": "Rayane est architecte. Son travail porte sur la création d''espaces contemporains, durables et sensibles, au service des personnes et des lieux.\n\nChaque projet part du site, de la lumière et des matières pour composer des lieux simples, justes et faits pour durer.", "location": "", "email": "", "phone": "", "instagram": "", "linkedin": "", "categories": ["Résidentiel", "Commercial", "Culturel", "Public"]}');
INSERT OR IGNORE INTO projects (id,title,category,year,location,description,images,pdf,published,example,position) VALUES ('ex-villa-des-pins','Villa des Pins','Résidentiel','2023','','Une maison contemporaine intégrée dans son environnement naturel, jouant avec la lumière, les matières brutes et la relation intérieur-extérieur.','["/examples/ex-villa-1.jpg", "/examples/ex-villa-2.jpg", "/examples/ex-villa-3.jpg", "/examples/ex-villa-4.jpg", "/examples/ex-villa-5.jpg"]',NULL,1,1,0);
INSERT OR IGNORE INTO projects (id,title,category,year,location,description,images,pdf,published,example,position) VALUES ('ex-villa-azur','Villa Azur','Résidentiel','2024','','Une villa blanche organisée autour de sa piscine : de grandes baies coulissantes, des terrasses en porte-à-faux et une lumière méditerranéenne qui traverse toute la maison.','["/examples/ex-azur-1.jpg", "/examples/ex-azur-2.jpg", "/examples/ex-azur-3.jpg"]',NULL,1,1,1);
INSERT OR IGNORE INTO projects (id,title,category,year,location,description,images,pdf,published,example,position) VALUES ('ex-centre-culturel','Centre culturel','Culturel','2022','','Un équipement public ouvert sur la ville : des volumes blancs facettés, une grande verrière et des salles baignées de lumière naturelle.','["/examples/ex-culture-1.jpg", "/examples/ex-culture-2.jpg"]',NULL,1,1,2);
INSERT OR IGNORE INTO projects (id,title,category,year,location,description,images,pdf,published,example,position) VALUES ('ex-bureaux-horizon','Bureaux Horizon','Commercial','2021','','Un immeuble de bureaux à la façade vitrée rythmée, pensé pour le confort thermique et des plateaux de travail flexibles.','["/examples/ex-bureaux-1.jpg", "/examples/ex-bureaux-2.jpg", "/examples/ex-bureaux-3.jpg"]',NULL,1,1,3);
